const fullNameField = document.getElementById('fullName');
const emailField = document.getElementById('email');
const phoneField = document.getElementById('phone');

const fullNameError = document.getElementById('fullNameError');
const emailError = document.getElementById('emailError');
const phoneError = document.getElementById('phoneError');

const fieldsToValidate = [
    { field: fullNameField, errorElement: fullNameError, validator: validateFullName },
    { field: emailField, errorElement: emailError, validator: validateEmail },
    { field: phoneField, errorElement: phoneError, validator: validatePhone }
];

function validateFullName(value) {
    if (!value.trim()) {
        return 'Full name is required';
    }
    if (value.trim().length < 2) {
        return 'Full name must be at least 2 characters';
    }
    return '';
}

function validateEmail(value) {
    if (!value.trim()) {
        return 'Email address is required';
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
        return 'Please enter a valid email address';
    }
    return '';
}

function validatePhone(value) {
    if (!value.trim()) {
        return '';
    }
    const phoneRegex = /^(\+?1\s?)?(\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;
    if (!phoneRegex.test(value)) {
        return 'Please enter a valid phone number';
    }
    return '';
}

function showError(field, errorElement, message) {
    if (message) {
        field.classList.add('input-error');
        errorElement.textContent = message;
        errorElement.classList.add('show');
    } else {
        field.classList.remove('input-error');
        errorElement.textContent = '';
        errorElement.classList.remove('show');
    }
}

function validateField(fieldConfig) {
    const message = fieldConfig.validator(fieldConfig.field.value);
    showError(fieldConfig.field, fieldConfig.errorElement, message);
    return message === '';
}

fieldsToValidate.forEach(fieldConfig => {
    fieldConfig.field.addEventListener('blur', () => {
        validateField(fieldConfig);
    });

    fieldConfig.field.addEventListener('input', () => {
        if (fieldConfig.errorElement.classList.contains('show')) {
            validateField(fieldConfig);
        }
    });
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    let isValid = true;
    fieldsToValidate.forEach(fieldConfig => {
        if (!validateField(fieldConfig)) {
            isValid = false;
        }
    });

    if (isValid) {
        handleFormSubmit();
    }
});

function handleFormSubmit() {
    const fullName = fullNameField.value.trim();
    const email = emailField.value.trim();
    const phone = phoneField.value.trim();

    console.log('Form submitted successfully:', {
        fullName,
        email,
        phone: phone || 'Not provided'
    });

    alert('Thank you for contacting us! We will get back to you soon.');
    form.reset();
    clearAllErrors();
}

